def can_make_abc(s):
    # Check if the row is already 'abc'
    if s == 'abc':
        return True

    # Check if the row is 'abc' after swapping two cards
    if s == 'abc' and s[0] == 'a' and s[1] == 'b' and s[2] == 'c':
        return True

    # Check if the row is 'abc' after swapping three cards
    if s == 'abc' and s[0] == 'a' and s[1] == 'b' and s[2] == 'c' and s[3] == 'a':
        return True

    return False

