def find_good_sequences(l, r):
    dp = [[0 for _ in range(l, r)] for _ in range(l, r)]
    for i in range(l):
        for j in range(l):
            if dp[i][j] == 0:
                dp[i][j] = 1
            else:
                dp[i][j] = dp[i-1][j-1] + dp[i-1][j] + dp[i-1][j-1]
    return dp[r]

