def minimum_boxes(apple, capacity):
    # Create a dictionary to store the number of boxes used for each pack
    boxes = {}

    # Iterate over the apple array
    for i in range(len(apple)):
        # If the current pack has more than one apple, add it to the boxes dictionary
        if apple[i] > 1:
            boxes[i] += 1
        # If the current pack has less than one apple, add it to the boxes dictionary
        else:
            boxes[i] += 1

    # Iterate over the capacity array
    for i in range(len(capacity)):
        # If the current capacity is greater than or equal to the current number of apples, add it to the boxes dictionary
        if capacity[i] >= boxes[i]:
            boxes[i] += 1

    # Return the minimum number of boxes
    return min(boxes)

